import json

with open('/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-43d6a972.json') as f:
    raw_demos = json.load(f)

def check_specials():
    for i, entry in enumerate(raw_demos):
        grid = entry['input']['values']
        out = entry['output']['values']
        h, w = len(grid), len(grid[0])

        row_divs = sorted(entry['row_divs'])
        col_divs = sorted(entry['col_divs'])

        # Row regions: from r_start to rd-1 for each divider
        if row_divs:
            row_ranges = [[0, row_divs[0]-1]]
            for j in range(1, len(row_divs)):
                row_ranges.append([row_divs[j-1]+1, row_divs[j]-1])
            row_ranges.append([row_divs[-1]+1, h-1])
        else:
            row_ranges = [[0, h-1]]

        # Col regions: from c_start to cd-1 for each divider
        if col_divs:
            col_ranges = [[0, col_divs[0]-1]]
            for j in range(1, len(col_divs)):
                col_ranges.append([col_divs[j-1]+1, col_divs[j]-1])
            col_ranges.append([col_divs[-1]+1, w-1])
        else:
            col_ranges = [[0, w-1]]

        print(f"\nDemo {i+1}:")
        print(f"  Row ranges: {row_ranges}")
        print(f"  Col ranges: {col_ranges}")

        first_cell = grid[0][0]
        special_values = set(v for row in grid for v in row if v != first_cell)
        print(f"  Special values: {sorted(special_values)}")
        print(f"  First cell: {first_cell}")

        # Count first_cell in each region
        for r_out in range(len(out)):
            for c_out in range(len(out[0])):
                if r_out >= len(row_ranges):
                    r_range = [h-1, h-1]
                else:
                    r_range = row_ranges[r_out]

                if c_out >= len(col_ranges):
                    c_range = [w-1, w-1]
                else:
                    c_range = col_ranges[c_out]

                # Count first_cell and check for special
                first_cell_count = 0
                for r in range(r_range[0], r_range[1] + 1):
                    for c in range(c_range[0], c_range[1] + 1):
                        if 0 <= r < h and 0 <= c < w:
                            if grid[r][c] == first_cell:
                                first_cell_count += 1
                            elif grid[r][c] != first_cell and grid[r][c] in special_values:
                                # Skip - we want first_cell count
                                pass

                # Get the actual special values in this region
                special_in_region = []
                for r in range(r_range[0], r_range[1] + 1):
                    for c in range(c_range[0], c_range[1] + 1):
                        if 0 <= r < h and 0 <= c < w:
                            if grid[r][c] != first_cell:
                                special_in_region.append(grid[r][c])

                print(f"  out[{r_out},{c_out}]={out[r_out][c_out]}: rc={r_range}, cc={c_range}, first_cell_count={first_cell_count}, specials={set(special_in_region)}")

check_specials()

